using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;

namespace TutorFlow.Api.Tests.Llm;

public sealed class LlamadaDeterministaApiTests
{
    private const string Normativa = "¿Cuál es la nota mínima para aprobar una asignatura?";
    private const string RespuestaNormativa = "Una asignatura se aprueba con 3.0.";
    private const string PreguntaConHerramienta = "¿Cuál es mi promedio ponderado del periodo?";
    private const string PropiedadTemperatura = "temperature";
    private const string PropiedadSemilla = "seed";

    public static TheoryData<string?, string> ProveedoresCompatiblesConOpenAi => new()
    {
        { null, "ollama" },
        { "[llave-redactada]", "openai" },
        { "gsk_LLAVEABC123", "groq" },
        { "sk-or-LLAVE-ABC123", "openrouter" },
        { "AIzaLLAVEABC123", "gemini" }
    };

    public static TheoryData<string?, string, int> SemillasConfiguradas => new()
    {
        { null, "ollama", 42 },
        { "[llave-redactada]", "openai", 42 },
        { null, "ollama", 0 },
        { null, "ollama", int.MaxValue },
        { "gsk_LLAVEABC123", "groq", 7 }
    };

    private static Dictionary<string, string?> Entorno(string? llave) =>
        llave is null ? [] : new Dictionary<string, string?> { ["LLM_API_KEY"] = llave };

    private static Dictionary<string, string?> Configuracion(string? semilla)
    {
        var configuracion = FabricaApi.Precios("1.0", "5.0");
        if (semilla is not null)
        {
            configuracion["Llm:Semilla"] = semilla;
        }

        return configuracion;
    }

    private static FabricaApi Fabrica(string? llave, ManejadorLlmFalso manejador, string? semilla = null) =>
        new(configuracion: Configuracion(semilla), variablesEntorno: Entorno(llave), reemplazarLlm: false, manejadorHttp: manejador);

    private static ManejadorLlmFalso ConUnaRespuesta() =>
        new((p, _) => RespuestasProveedor.Texto(p, RespuestaNormativa, 5));

    private static ManejadorLlmFalso ConHerramienta() =>
        new((p, n) => n == 0 ? RespuestasProveedor.LlamadaAHerramienta(p, 5) : RespuestasProveedor.Texto(p, "Datos revisados.", 5));

    private static JsonElement Cuerpo(PeticionLlm peticion) => JsonElement.Parse(peticion.Cuerpo);

    [Theory]
    [MemberData(nameof(ProveedoresCompatiblesConOpenAi))]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192ab_Los_adaptadores_compatibles_con_OpenAI_envian_temperatura_0_y_semilla_1(string? llave, string proveedor)
    {
        Assert.NotEmpty(proveedor);
        var manejador = ConUnaRespuesta();
        using var fabrica = Fabrica(llave, manejador);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        Assert.Equal(200, respuesta.Estado);
        var peticion = Assert.Single(manejador.Peticiones);
        var cuerpo = Cuerpo(peticion);
        Assert.Equal(0, cuerpo.GetProperty(PropiedadTemperatura).GetDouble());
        Assert.Equal(1, cuerpo.GetProperty(PropiedadSemilla).GetInt64());
    }

    [Fact]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192c_Anthropic_envia_temperatura_0_y_ninguna_semilla()
    {
        var manejador = ConUnaRespuesta();
        using var fabrica = Fabrica("[llave-redactada]", manejador);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        Assert.Equal(200, respuesta.Estado);
        var cuerpo = Cuerpo(Assert.Single(manejador.Peticiones));
        Assert.Equal(0, cuerpo.GetProperty(PropiedadTemperatura).GetDouble());
        Assert.False(cuerpo.TryGetProperty(PropiedadSemilla, out _));
    }

    [Fact]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192c_Anthropic_no_envia_semilla_aunque_Llm_Semilla_este_configurada()
    {
        var manejador = ConUnaRespuesta();
        using var fabrica = Fabrica("[llave-redactada]", manejador, "42");

        await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        Assert.False(Cuerpo(Assert.Single(manejador.Peticiones)).TryGetProperty(PropiedadSemilla, out _));
    }

    [Theory]
    [MemberData(nameof(SemillasConfiguradas))]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192d_La_semilla_configurada_llega_al_proveedor(string? llave, string proveedor, int semilla)
    {
        Assert.NotEmpty(proveedor);
        var manejador = ConUnaRespuesta();
        using var fabrica = Fabrica(llave, manejador, semilla.ToString(System.Globalization.CultureInfo.InvariantCulture));

        await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        var cuerpo = Cuerpo(Assert.Single(manejador.Peticiones));
        Assert.Equal(semilla, cuerpo.GetProperty(PropiedadSemilla).GetInt64());
        Assert.Equal(0, cuerpo.GetProperty(PropiedadTemperatura).GetDouble());
    }

    [Theory]
    [InlineData(null)]
    [InlineData("[llave-redactada]")]
    [InlineData("[llave-redactada]")]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192abc_Toda_peticion_del_ciclo_de_herramientas_lleva_temperatura_0(string? llave)
    {
        var manejador = ConHerramienta();
        using var fabrica = Fabrica(llave, manejador);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaConHerramienta);

        Assert.Equal(200, respuesta.Estado);
        Assert.Equal(2, manejador.Peticiones.Count);
        Assert.All(manejador.Peticiones, p => Assert.Equal(0, Cuerpo(p).GetProperty(PropiedadTemperatura).GetDouble()));
    }

    [Theory]
    [InlineData(null)]
    [InlineData("[llave-redactada]")]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("RF", "D-47")]
    public async Task ESC_192ab_Toda_peticion_del_ciclo_de_herramientas_lleva_la_misma_semilla(string? llave)
    {
        var manejador = ConHerramienta();
        using var fabrica = Fabrica(llave, manejador);

        await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaConHerramienta);

        Assert.All(manejador.Peticiones, p => Assert.Equal(1, Cuerpo(p).GetProperty(PropiedadSemilla).GetInt64()));
    }
}
using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;

namespace TutorFlow.Api.Tests.Llm;

public sealed class TemperaturaConfiguradaApiTests
{
    private const string Normativa = "¿Cuál es la nota mínima para aprobar una asignatura?";
    private const string PreguntaPromedio = "¿Cuál es mi promedio?";
    private const string PropiedadTemperatura = "temperature";
    private const string PropiedadSemilla = "seed";
    private const string LlaveDeOpenAi = "[llave-redactada]";
    private const string LlaveDeAnthropic = "[llave-redactada]";

    private static FabricaApi Fabrica(string? llave, ManejadorLlmFalso manejador, string temperatura)
    {
        var configuracion = FabricaApi.Precios("1.0", "5.0");
        configuracion["Llm:Temperatura"] = temperatura;
        var entorno = llave is null ? new Dictionary<string, string?>() : new Dictionary<string, string?> { ["LLM_API_KEY"] = llave };
        return new FabricaApi(configuracion: configuracion, variablesEntorno: entorno, reemplazarLlm: false, manejadorHttp: manejador);
    }

    private static JsonElement Cuerpo(PeticionLlm peticion) => JsonElement.Parse(peticion.Cuerpo);

    private static ManejadorLlmFalso ConUnaRespuesta() =>
        new((p, _) => RespuestasProveedor.Texto(p, "Una asignatura se aprueba con 3.0.", 5));

    [Theory]
    [InlineData(null, "0.3", true, "e")]
    [InlineData(LlaveDeAnthropic, "0.1", false, "f")]
    [InlineData(LlaveDeOpenAi, "0.2", true, "g")]
    [Trait("CA", "CA-20")]
    [Trait("CA", "CA-23")]
    [Trait("ESC", "ESC-192")]
    [Trait("D", "D-59")]
    public async Task ESC_192efg_La_temperatura_configurada_llega_al_proveedor_y_la_semilla_solo_a_los_compatibles_con_OpenAI(string? llave, string temperatura, bool llevaSemilla, string caso)
    {
        Assert.NotEmpty(caso);
        var manejador = ConUnaRespuesta();
        using var fabrica = Fabrica(llave, manejador, temperatura);

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        Assert.Equal(200, respuesta.Estado);
        var cuerpo = Cuerpo(Assert.Single(manejador.Peticiones));
        Assert.Equal(double.Parse(temperatura, System.Globalization.CultureInfo.InvariantCulture), cuerpo.GetProperty(PropiedadTemperatura).GetDouble());
        Assert.Equal(llevaSemilla, cuerpo.TryGetProperty(PropiedadSemilla, out var semilla));
        if (llevaSemilla)
        {
            Assert.Equal(1, semilla.GetInt64());
        }
    }

    [Fact]
    [Trait("CA", "CA-23")]
    [Trait("ESC", "ESC-199")]
    [Trait("D", "D-59")]
    public async Task ESC_199f_Con_ollama_y_temperatura_0_2_el_log_de_arranque_la_registra_y_toda_peticion_incluida_la_del_reintento_la_lleva_con_semilla_1()
    {
        var manejador = new ManejadorLlmFalso((p, _) => RespuestasProveedor.Texto(p, "Tu promedio es 4.40.", 5));
        using var fabrica = Fabrica(null, manejador, "0.2");

        await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaPromedio);

        Assert.Equal(2, manejador.Peticiones.Count);
        Assert.All(manejador.Peticiones, peticion =>
        {
            var cuerpo = Cuerpo(peticion);
            Assert.Equal(0.2, cuerpo.GetProperty(PropiedadTemperatura).GetDouble());
            Assert.Equal(1, cuerpo.GetProperty(PropiedadSemilla).GetInt64());
        });
        Assert.Contains(fabrica.Logs.Mensajes, m => m.Contains("0.2", StringComparison.Ordinal) && (m.Contains("emperatura", StringComparison.Ordinal) || m.Contains("emperature", StringComparison.Ordinal)));
    }

    [Fact]
    [Trait("CA", "CA-20")]
    [Trait("ESC", "ESC-192")]
    [Trait("D", "D-59")]
    public async Task ESC_192_Sin_configurar_la_temperatura_el_defecto_es_0_en_el_cuerpo_y_en_el_log_de_arranque()
    {
        var manejador = ConUnaRespuesta();
        var configuracion = FabricaApi.Precios("1.0", "5.0");
        using var fabrica = new FabricaApi(configuracion: configuracion, variablesEntorno: new Dictionary<string, string?>(), reemplazarLlm: false, manejadorHttp: manejador);

        await fabrica.PreguntarEstudianteAsync("EST-001", Normativa);

        Assert.Equal(0, Cuerpo(Assert.Single(manejador.Peticiones)).GetProperty(PropiedadTemperatura).GetDouble());
        Assert.Contains(fabrica.Logs.Mensajes, m => (m.Contains("emperatura", StringComparison.Ordinal) || m.Contains("emperature", StringComparison.Ordinal)) && m.Contains('0', StringComparison.Ordinal));
    }
}
using TutorFlow.Api.Tests.Dobles;
using static TutorFlow.Api.Tests.Dobles.ConfiguracionDePrueba;

namespace TutorFlow.Api.Tests.Operacion;

public sealed class ConfiguracionDeRecuperacionYSemillaApiTests
{
    private const string PuntajeRelativo = "Conocimiento:PuntajeRelativoMinimo";
    private const string Semilla = "Llm:Semilla";
    private const string ReglaPuntaje = "entero de 1 a 100";
    private const string ReglaSemilla = "entero de 0 a 2147483647";

    public static TheoryData<string, string, string> ValoresInvalidos => new()
    {
        { PuntajeRelativo, "0", ReglaPuntaje },
        { PuntajeRelativo, "101", ReglaPuntaje },
        { PuntajeRelativo, "-1", ReglaPuntaje },
        { PuntajeRelativo, "50.0", ReglaPuntaje },
        { PuntajeRelativo, "50,5", ReglaPuntaje },
        { PuntajeRelativo, "cincuenta", ReglaPuntaje },
        { PuntajeRelativo, " 50 ", ReglaPuntaje },
        { Semilla, "-1", ReglaSemilla },
        { Semilla, "2147483648", ReglaSemilla },
        { Semilla, "1.5", ReglaSemilla },
        { Semilla, "uno", ReglaSemilla },
        { Semilla, "1e3", ReglaSemilla },
        { Semilla, " 1 ", ReglaSemilla }
    };

    public static TheoryData<string, string> ValoresEnElLimite => new()
    {
        { PuntajeRelativo, "1" },
        { PuntajeRelativo, "100" },
        { PuntajeRelativo, "50" },
        { Semilla, "0" },
        { Semilla, "1" },
        { Semilla, "2147483647" },
        { PuntajeRelativo, "" },
        { Semilla, "" }
    };

    private static ResultadoArranque Iniciar(Dictionary<string, string?> configuracion)
    {
        using var fabrica = new FabricaApi(configuracion: configuracion, variablesEntorno: EntornoConLlave());
        return ResultadoArranque.De(fabrica);
    }

    [Theory]
    [MemberData(nameof(ValoresInvalidos))]
    [Trait("CA", "CA-15")]
    [Trait("ESC", "ESC-188")]
    [Trait("RF", "RNF-05")]
    public void ESC_188c_Un_valor_invalido_impide_arrancar_con_la_linea_exacta(string clave, string valor, string regla)
    {
        var resultado = Iniciar(new Dictionary<string, string?> { [clave] = valor });

        Assert.False(resultado.Arranco, "el arranque debió fallar antes de aceptar peticiones");
        Assert.Contains(Invalida(clave, valor, regla), resultado.LineasDelError);
        Assert.DoesNotContain(LlaveFalsa, resultado.TextoCompleto, StringComparison.Ordinal);
    }

    [Theory]
    [MemberData(nameof(ValoresEnElLimite))]
    [Trait("CA", "CA-15")]
    [Trait("ESC", "ESC-188")]
    [Trait("RF", "RNF-05")]
    public void ESC_188c_Los_valores_en_el_limite_y_los_vacios_arrancan_sin_advertencia(string clave, string valor)
    {
        var resultado = Iniciar(new Dictionary<string, string?> { [clave] = valor });

        Assert.True(resultado.Arranco, string.Join("\n", resultado.LineasDelError));
        Assert.DoesNotContain(resultado.LineasDeLaConsola, l => l.StartsWith(ResultadoArranque.PrefijoInvalida, StringComparison.Ordinal) || l.StartsWith(ResultadoArranque.PrefijoIgnorada, StringComparison.Ordinal));
    }

    [Fact]
    [Trait("CA", "CA-15")]
    [Trait("ESC", "ESC-188")]
    [Trait("RF", "RNF-05")]
    public void ESC_188c_Se_informan_a_la_vez_el_puntaje_relativo_y_la_semilla_invalidos()
    {
        var resultado = Iniciar(new Dictionary<string, string?> { [PuntajeRelativo] = "0", [Semilla] = "-1" });

        Assert.False(resultado.Arranco);
        Assert.Contains(Invalida(PuntajeRelativo, "0", ReglaPuntaje), resultado.LineasDelError);
        Assert.Contains(Invalida(Semilla, "-1", ReglaSemilla), resultado.LineasDelError);
    }
}

