using System.Text.Json;
using TutorFlow.Api.Tests.Dobles;

namespace TutorFlow.Api.Tests.Operacion;

[Collection("Consola")]
public sealed class AuditoriaDetalleYArchivoApiTests : IDisposable
{
    private const string FechaDelReloj = "2026-11-22";
    private static readonly string[] CamposDeUnDato = ["estudianteId", "programaId", "recurso", "asignatura"];
    private static readonly string[] ValoresProhibidos = ["48", "4.39", "4.5", "4.8", "4.1", "4.0", "3.8"];
    private static readonly string[] EstudiantesDeAdm = ["EST-004", "EST-005", "EST-006"];

    private readonly string _carpeta = Path.Combine(Path.GetTempPath(), $"tutorflow-auditoria-{Guid.NewGuid():N}");

    public void Dispose()
    {
        if (Directory.Exists(_carpeta))
        {
            Directory.Delete(_carpeta, recursive: true);
        }
    }

    private string ArchivoDelDia => Path.Combine(_carpeta, $"auditoria-{FechaDelReloj}.jsonl");

    private FabricaApi FabricaConArchivo(string? ruta = null) =>
        new(
            llm: ClienteLlmDoble.ConsultaDatos(redactar: _ => "Resumen de tus datos académicos."),
            configuracion: new Dictionary<string, string?> { ["Auditoria:Ruta"] = ruta ?? _carpeta },
            auditoriaReal: true);

    private static async Task<IReadOnlyList<string>> CapturarConsolaAsync(Func<Task> accion)
    {
        var original = Console.Out;
        using var escritor = new EscritorSincronizado();
        Console.SetOut(escritor);
        try
        {
            await accion();
        }
        finally
        {
            Console.SetOut(original);
        }

        return escritor.ToString()
            .Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(l => l.TrimEnd('\r'))
            .Where(l => l.StartsWith('{') && l.Contains("\"correlationId\"", StringComparison.Ordinal))
            .ToList();
    }

    private async Task<JsonElement> EventoDe(string rol, string id, string pregunta)
    {
        using var fabrica = FabricaConArchivo();
        var lineas = await CapturarConsolaAsync(() => fabrica.PreguntarAsync(rol, id, pregunta));
        return JsonElement.Parse(Assert.Single(lineas));
    }

    private static JsonElement DatosConsultados(JsonElement evento)
    {
        Assert.True(evento.TryGetProperty("datosConsultados", out var datos), "el evento no tiene datosConsultados");
        Assert.Equal(JsonValueKind.Array, datos.ValueKind);
        return datos;
    }

    private static string Campo(JsonElement dato, string nombre) =>
        dato.TryGetProperty(nombre, out var valor) ? valor.GetString() ?? string.Empty : string.Empty;

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-143")]
    public async Task ESC_143_Las_faltas_en_bases_de_datos_dejan_una_entrada_de_asistencia_con_el_codigo_de_la_asignatura()
    {
        var evento = await EventoDe("estudiante", "EST-001", "¿Cuántas faltas tengo en Bases de Datos?");

        var datos = DatosConsultados(evento).EnumerateArray().ToList();
        Assert.Contains(datos, d =>
            Campo(d, "estudianteId") == "EST-001"
            && Campo(d, "programaId") == "ING-SIS"
    public async Task ESC_148_El_400_por_rol_invalido_enmascara_a_los_terceros_en_la_pregunta_auditada()
    {
        using var fabrica = await FabricaConRegistroCargadoAsync();

        var respuesta = await fabrica.PreguntarAsync("admin", "EST-001", PreguntaConTerceros);

        Assert.Equal(400, respuesta.Estado);
        Assert.Equal(PreguntaEnmascarada, Ultimo(fabrica).Pregunta);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-148")]
    public async Task ESC_148_El_429_enmascara_a_los_terceros_en_la_pregunta_auditada()
    {
        using var fabrica = await FabricaConRegistroCargadoAsync(ConfiguracionDePrueba.TasaPorMinuto(PeticionesPorMinuto));
        for (var i = 1; i < PeticionesPorMinuto; i++)
        {
            await fabrica.PreguntarEstudianteAsync("EST-001", "¿Cuál es la nota mínima para aprobar?", IpDelLimite);
        }

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaConTerceros, IpDelLimite);
        var superada = await fabrica.PreguntarEstudianteAsync("EST-001", PreguntaConTerceros, IpDelLimite);

        Assert.Equal(403, respuesta.Estado);
        Assert.Equal(429, superada.Estado);
        Assert.Equal(PreguntaEnmascarada, Ultimo(fabrica).Pregunta);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-148")]
    public async Task ESC_148_El_403_por_identidad_invalida_enmascara_a_los_terceros_en_la_pregunta_auditada()
    {
        using var fabrica = await FabricaConRegistroCargadoAsync();

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-999", PreguntaConTerceros);

        Afirmaciones.Negativa(respuesta, "estudiante");
        var evento = Ultimo(fabrica);
        Assert.Equal(MotivoDenegacion.IdentidadInvalida, evento.MotivoDenegacion);
        Assert.Equal(PreguntaEnmascarada, evento.Pregunta);
    }

    [Fact]
    [Trait("CA", "CA-08")]
    [Trait("ESC", "ESC-148")]
    public async Task ESC_148_El_413_registra_la_pregunta_como_no_evaluada()
    {
        using var fabrica = await FabricaConRegistroCargadoAsync();
        var cuerpo = CuerpoConTerceros(new string('x', BytesDeCuerpoExcesivo));
    ResultadoAuditoria Resultado,
    MotivoDenegacion? MotivoDenegacion,
    IReadOnlyList<string> EstudiantesConsultados,
    IReadOnlyList<RecursoConsultado> RecursosConsultados,
    IReadOnlyList<Cita> Citas,
    int Tokens,
    decimal CostoUsd,
    long DuracionMs,
    bool PrecioDesconocido)
{
    public IReadOnlyList<DatoConsultado> DatosConsultados { get; init; } = [];

    public string? IdSolicitado { get; init; }

    public bool Reintento { get; init; }

    public bool ContextoTruncado { get; init; }
}

