        await PreguntarAsync(fabrica, Limite + 1, Conexion);
        fabrica.Reloj.Fijar(fabrica.Reloj.AhoraUtc + TimeSpan.FromHours(1));

        var respuesta = await fabrica.PreguntarEstudianteAsync("EST-001", Pregunta, Conexion);

